perl -e '
use strict;
use warnings;
use File::Find;
use File::Basename;

my $root = "/bench/repo";

my @entities = qw(
  Attachment Memo MemoRelation InstanceSetting User UserSetting
  IdentityProvider Inbox Reaction MemoShare UserIdentity
  AuthenticationConfigState AuthenticationConfigMutation
  RowStatus Visibility Role InboxStatus MemoRelationType
);

# collect proto message types
my @proto_types;
opendir(my $dh, "$root/proto/store") or die $!;
while (my $f = readdir($dh)) {
  next unless $f =~ /\.proto$/;
  open(my $fh, "<", "$root/proto/store/$f") or die $!;
  while (<$fh>) {
    push @proto_types, $1 if /^message\s+(\w+)/;
  }
  close $fh;
}
closedir $dh;
print "PROTO TYPES: @proto_types\n";

my @go_files;
find({
  wanted => sub {
    return unless /\.go$/;
    return if $File::Find::name =~ /\/\.git\//;
    my $rel = $File::Find::name;
    $rel =~ s/^\Q$root\E\///;
    return if $rel =~ /^store\//;
    push @go_files, $File::Find::name;
  },
  no_chdir => 1,
}, $root);

print "Go files outside data layer: ", scalar(@go_files), "\n";

my %pkgs;
for my $f (@go_files) {
  my $rel = $f;
  $rel =~ s/^\Q$root\E\///;
  my $pkg = dirname($rel);
  $pkgs{$pkg} = 1;
}
print "Packages:\n";
for my $p (sort keys %pkgs) { print "  $p\n"; }

sub count_type {
  my ($prefix, $type) = @_;
  my %hit;
  for my $f (@go_files) {
    open(my $fh, "<", $f) or next;
    local $/;
    my $text = <$fh>;
    close $fh;
    if ($text =~ /\b\Q$prefix\E\.\Q$type\E\b/) {
      my $rel = $f;
      $rel =~ s/^\Q$root\E\///;
      $hit{dirname($rel)} = 1;
    }
  }
  return keys %hit;
}

print "\n=== store.Type references ===\n";
my @results;
for my $t (@entities) {
  my @hit = count_type("store", $t);
  push @results, [scalar(@hit), $t, [sort @hit]];
}
@results = sort { $b->[0] <=> $a->[0] || $a->[1] cmp $b->[1] } @results;
for my $r (@results) {
  printf "%3d  store.%s\n", $r->[0], $r->[1];
  for my $p (@{$r->[2]}) {
    print "       - $p\n";
  }
}

print "\n=== storepb.Type references ===\n";
my %seen;
my @results2;
for my $t (@proto_types) {
  next if $seen{$t}++;
  my @hit = count_type("storepb", $t);
  push @results2, [scalar(@hit), $t, [sort @hit]];
}
@results2 = sort { $b->[0] <=> $a->[0] || $a->[1] cmp $b->[1] } @results2;
for my $r (@results2) {
  next if $r->[0] == 0;
  printf "%3d  storepb.%s\n", $r->[0], $r->[1];
  for my $p (@{$r->[2]}) {
    print "       - $p\n";
  }
}
'

