for my $t (@proto_types) {
  next if $seen{$t}++;
  my @hit = count_type("storepb", $t);
  push @results2, [scalar(@hit), $t, [sort @hit]];
}
@results2 = sort { $b->[0] <=> $a->[0] || $a->[1] cmp $b->[1] } @results2;
for my $r (@results2) {
  next if $r->[0] == 0;
  printf "%3d  storepb.%s\n", $r->[0], $r->[1];
  for my $p (@{$r->[2]}) {
    print "       - $p\n";
  }
}
